window.docContents[38].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--The-Substitution-Lemma":{"contents":"Now we come to the conceptual heart of the proof that reduction\npreserves types — namely, the observation that substitution\npreserves types.\n\n\n\nThe substitution lemma says:* Suppose we have a term t with a free variable x, and\n  suppose we've been able to assign a type T to t under the\n  assumption that x has some type U.* Also, suppose that we have some other term v and that we've\n  shown that v has type U.* Then we can substitute v for each of the occurrences of\n  x in t and obtain a new term that still has type T.\n\n\n\ntheorem substitution_preserves_typing (Γ : Context) (x : String) (U : Ty)\n    (t v : Tm) (T : Ty)\n    (hT : <{ ~x ↦ ~U ; ~Γ ⊢ ~t ⦂ ~T }>) (hv : <{ ∅ ⊢ ~v ⦂ ~U }>) :\n    <{ ~Γ ⊢ [~x := ~v] ~t ⦂ ~T }> := by\n  -- By induction on `t`; in each case we get at the derivation of `hT`.\n  induction t generalizing Γ T with\n  | var y =>\n    cases hT with\n    | var _ _ _ h =>\n      by_cases hxy : x = y\n      · subst hxy\n        rw [PartialMap.update_eq] at h\n        rw [subst_var_eq]\n        have hUT : U = T := Option.some.inj h\n        subst hUT\n        exact weakening_empty _ _ _ hv\n      · rw [PartialMap.update_neq _ _ _ hxy] at h\n        rw [subst_var_ne _ _ _ hxy]\n        exact .var _ y _ h\n  | app t₁ t₂ ih₁ ih₂ =>\n    cases hT with\n    | app _ _ _ _ _ h₁ h₂ => rw [subst_app]; exact .app _ _ _ _ _ (ih₁ _ _ h₁) (ih₂ _ _ h₂)\n  | abs y S t₁ ih =>\n    cases hT with\n    | abs _ _ _ _ _ h =>\n      by_cases hxy : x = y\n      · subst hxy\n        rw [subst_abs_eq]\n        rw [PartialMap.update_shadow] at h\n        exact .abs _ _ _ _ _ h\n      · rw [subst_abs_ne _ _ _ _ _ hxy]\n        rw [PartialMap.update_permute _ _ _ _ _ (Ne.symm hxy)] at h\n        exact .abs _ _ _ _ _ (ih _ _ h)\n  | tru => cases hT with | tru => rw [subst_tru]; exact .tru _\n  | fls => cases hT with | fls => rw [subst_fls]; exact .fls _\n  | ite c t e ihc iht ihe =>\n    cases hT with\n    | ite _ _ _ _ _ h₁ h₂ h₃ =>\n      rw [subst_ite]\n      exact .ite _ _ _ _ _ (ihc _ _ h₁) (iht _ _ h₂) (ihe _ _ h₃)\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC\u0009Preservation","header":"6.3.2. The Substitution Lemma","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Preservation--The-Substitution-Lemma"}});